/**
 * @param {number} index
 */
export function getColor(index?: number) {
  const mColors = [
    '#F44336',
    '#E91E63',
    '#9C27B0',
    '#673AB7',
    '#3F51B5',
    '#2196F3',
    '#2196F3',
    '#00BCD4',
    '#009688',
    '#4CAF50',
    '#8BC34A',
    '#CDDC39',
    '#FFEB3B',
    '#FFC107',
    '#FF9800',
    '#FF5722',
    '#795548',
    '#9E9E9E',
  ];
  return mColors[typeof index === 'undefined' ? Math.round(Math.random() * mColors.length) : index];
}

export default getColor;
